'use strict';
let adaptiveData=null, adaptivePreview=null, adaptivePoll=null;
const taskLabels={goal:'Что должно получиться',task_type:'Тип задачи — сфера работы',starting_point:'Исходная точка',volume:'Объём — содержание и связи, которые нужно сохранить',complexity:'Начальная сложность и основание оценки',criteria:'Как проверить готовность',materials:'Необходимые материалы'};
const taskStatus={running:'ИИ выполняет задачу',awaiting_review:'Нужна проверка человеком',reviewed:'Проверка сохранена',failed:'Вызов не завершён'};
function adaptivePayload(){return {...Object.fromEntries(Object.keys(taskLabels).map(k=>[k,$('task-'+k).value])),rule_packs:[...document.querySelectorAll('[name=rule-pack]:checked')].map(el=>el.value),script_mode:$('task-scriptmode').checked,use_memory:$('task-memory').checked,use_project_check:$('task-project-check').checked,memory_ids:[...$('task-memory-ids').selectedOptions].map(el=>el.value),...($('task-stage').value?{plan_id:$('task-stage').value.split(':')[0],stage_id:$('task-stage').value.split(':')[1]}:{})};}
async function renderAdaptive(){
  clearTimeout(adaptivePoll);
  $('main').innerHTML=header('НАСТРОЙКА → ЗАДАЧА → ПРОВЕРКА → ИЗМЕНЕНИЕ','Настройка и задачи','Исходные требования сохраняются один раз. Следующие запросы используют их и опыт задач того же типа и модели.')+'<div id="workspace-message" role="status"></div><div id="adaptive-content">Загрузка…</div>';
  try{
    adaptiveData=await workspaceAPI('/api/adaptive');if(state.page!=='regulator')return;
    const p=adaptiveData.profile;
    $('adaptive-content').innerHTML=`<section class="card lab-card"><h2>1. Описание проекта</h2><p>Расскажите о проекте обычным текстом. ИИ выделит цель, требования и исходное состояние; вы проверите его понимание.</p><a class="primary-button" href="#onboarding">Описать проект с ИИ →</a><a class="secondary-button" href="#settings">Мой ИИ · настройки</a><details class="source-details"><summary>Расширенная настройка вручную</summary><p>${p.configured?'Настройка сохранена. Изменения создадут новую версию.':'Начните с трёх ответов. Типы задач появятся из практики; заранее перечислять их не нужно.'}</p><form id="adaptive-profile">${field('profile-purpose','Для какой работы используется протокол',p.purpose,true)}${field('profile-requirements','Обязательные требования к результату',p.requirements,true)}${field('profile-starting','Текущее состояние работы и исходные положения',p.starting_point,true)}${field('profile-known','Понятия, которые читатель уже понимает (через точку с запятой)',(p.known_terms||[]).join('; '))}<label class="form-label" for="profile-budget">Бюджет одного запроса в символах</label><input id="profile-budget" class="text-input" type="number" min="1000" max="100000" value="${p.character_budget||60000}"><p class="small-note">Это ограничение приложения, а не оценка способности ИИ. Оно учитывает протокол, настройку, материалы и опыт. Токены измеряются сервисом после вызова. Границы качества в начале неизвестны.</p><button class="primary-button">${p.configured?'Сохранить новую версию':'Сохранить и перейти к задаче'}</button></form></details></section><section class="card lab-card"><h2>2. Постановка и выполнение задачи</h2><p>ИИ может предложить постановку по цели и материалам. Уточните её перед выполнением. Используется ваш <a href="#settings">ИИ из настроек</a>.</p><form id="adaptive-task">${field('task-goal','Опишите задачу обычным текстом','',true)}${field('task-materials','Материалы задачи, если они есть','',true)}<div class="button-row"><button id="adaptive-intake" type="button" class="primary-button" ${p.configured?'':'disabled'}>Продолжить с ИИ: разобрать задачу →</button></div><p class="small-note">ИИ предложит тип, объём, сложность и способ проверки. Проверьте его понимание перед выполнением.</p><details id="task-understanding" class="source-details"><summary>Как ИИ понял задачу · уточнения и параметры</summary>${Object.entries(taskLabels).filter(([key])=>!['goal','materials'].includes(key)).map(([key,label])=>field('task-'+key,label,key==='starting_point'?(p.starting_point||''):'',true)).join('')}<fieldset class="rule-pack-options"><legend>Основания и проверки</legend><label class="checkbox-label"><input id="task-scriptmode" type="checkbox" checked>Проверять цитаты, основания утверждений, переходы и вычисления</label><label class="checkbox-label"><input id="task-memory" type="checkbox" checked>Найти материалы и подключить основания памяти</label><label class="checkbox-label"><input id="task-project-check" type="checkbox">Учесть успешную проверку текущей программы</label><button id="task-check-program" type="button" class="secondary-button">Запустить тесты проекта</button><div id="task-program-checks"></div><p class="small-note">Поиск выполняется локально. Полные найденные пункты и причины отбора видны до отправки. Понятность и достаточность оценивает человек.</p><label class="form-label" for="task-memory-ids">Записи, которые обязательно нужны (можно выбрать несколько)</label><select id="task-memory-ids" class="text-input" multiple>${(adaptiveData.memory_records||[]).map(r=>`<option value="${escapeHTML(r.id)}">${escapeHTML(r.title)} · ${escapeHTML(memoryStatuses[r.effective_status]||r.status)}</option>`).join('')}</select><p class="small-note">Действующие ограничения включаются независимо от выбора. Источники памяти обновляются в разделе «Ведение памяти проекта».</p><label class="form-label" for="task-stage">Выполнение этапа принятой схемы</label><select id="task-stage" class="text-input"><option value="">Самостоятельная задача</option>${(adaptiveData.plans||[]).flatMap(p=>p.stages.filter(stage=>['ready','needs_recheck'].includes(stage.status)&&!stage.blockers.length).map(stage=>`<option value="${p.id}:${stage.id}">${escapeHTML(p.goal)} → ${escapeHTML(stage.title)}</option>`)).join('')}</select></fieldset><fieldset class="rule-pack-options"><legend>Группы правил для этой задачи</legend><p class="small-note">Постоянное ядро включено всегда. По умолчанию включены все группы; исключайте только неприменимые к задаче. Предварительный запрос покажет точный состав.</p>${Object.entries({research:'Исследование, источники и формулы',memory:'Сохранение и продолжение работы',architecture:'Связанные этапы сложной задачи',external:'Актуальные внешние сведения'}).map(([key,label])=>`<label class="checkbox-label"><input type="checkbox" name="rule-pack" value="${key}" checked>${label}</label>`).join('')}</fieldset><div class="button-row"><button class="primary-button" ${p.configured?'':'disabled'}>Подготовить запрос</button></div></details></form><div id="adaptive-preview"></div></section><section><h2>3. Результаты и проверка человеком</h2><p>Принятие результата не устанавливает универсальную границу объёма. Здесь сохраняются основания оценки, ошибки и изменение способа следующей работы.</p><div id="adaptive-results"></div></section><section class="card lab-card"><h2>Связанные этапы работы</h2><p>Схема принимается для конкретной цели. Продолжение получает принятые человеком результаты входных этапов; изменённое основание требует повторной проверки.</p><div id="task-plans"></div><button id="plan-new" class="secondary-button">Составить схему этапов</button><div id="plan-editor"></div></section><details class="card lab-card"><summary>Наблюдения по задачам и хранение</summary><p>Сопоставление повторных замечаний не устанавливает их причину. Здесь можно проверить опыт и какие результаты используются как основания.</p><button id="task-diagnostics" class="secondary-button">Посмотреть наблюдения</button><div id="task-diagnostics-result"></div></details><details class="source-details"><summary>Предыдущий симулятор C/D</summary><p><a href="#regulator-previous">Открыть предыдущую версию</a></p></details>`;
    renderAdaptiveResults();renderTaskPlans();renderProgramChecks();
  }catch(error){workspaceError(error);}
}
function renderAdaptiveResults(preserve=false){
  const drafts=preserve?Array.from(document.querySelectorAll('[data-adaptive-review] input,[data-adaptive-review] textarea,[data-adaptive-review] select')).map(el=>[el.id,el.value]):[];
  if(!$('adaptive-results'))return;
  $('adaptive-results').innerHTML=adaptiveData.tasks.map(t=>`<details class="card lab-card" ${t.status==='awaiting_review'||t.status==='running'?'open':''}><summary><strong>${escapeHTML(t.goal)}</strong> · ${escapeHTML(taskStatus[t.status]||t.status)}</summary><p>${escapeHTML(t.task_type)} · ${escapeHTML(t.model.model||'')} · настройка ${t.profile.revision}</p><p>${escapeHTML(t.volume)}</p><p>${escapeHTML(t.notice)}</p><p>Применённый способ: ${escapeHTML(t.method||'Начальная проба, специальных поправок пока нет.')}</p><p>${t.characters} символов. ${escapeHTML(t.token_note)}</p>${runtimeManifestHTML(t.runtime)}${contextManifestHTML(t.retrieved_context)}${taskEvidenceHTML(t)}${t.checks?`<details open><summary>Автоматическая проверка ответа</summary><p>Состояние: ${escapeHTML({completed:'Проверка выполнена',failed:'Технический сбой',unavailable:'Скрипт недоступен'}[t.checks.status]||t.checks.status)}. Предупреждений: ${t.checks.warning_count??'неизвестно'}.</p><p>${escapeHTML(t.checks.limits)}</p>${t.checks.missing_protocol_sections.length?`<p>Отсутствующие пункты: ${escapeHTML(t.checks.missing_protocol_sections.join(', '))}</p>`:''}${t.checks.warnings.map(w=>`<p>${escapeHTML(w)}</p>`).join('')}</details>`:''}${t.usage?`<p>Расход сервиса: ${escapeHTML(JSON.stringify(t.usage))}</p>`:''}${t.answer?`<div class="response-text markdown">${t.answer.split(/\n\s*\n/).map(p=>`<p>${escapeHTML(p)}</p>`).join('')}</div>`:''}${taskCritiquesHTML(t)}${t.error?`<p role="status">${escapeHTML(t.error)}</p>`:''}${['awaiting_review','reviewed'].includes(t.status)?`<form data-adaptive-review="${escapeHTML(t.id)}"><label class="form-label" for="outcome-${t.id}">Решение человека</label><select id="outcome-${t.id}" name="outcome" class="text-input">${options({accepted:'Результат принят',revise:'Нужна доработка',rejected:'Результат отклонён'},t.review?.outcome||'revise')}</select>${field('evidence-'+t.id,'Что проверено и на каком основании',t.review?.evidence,true)}${field('error-'+t.id,'Обнаруженная ошибка или ограничение',t.review?.error,true)}${field('method-'+t.id,'Как изменить следующую работу этого типа с этой моделью',t.review?.next_method,true)}${field('complexity-'+t.id,'Поправка к оценке сложности и её основание',t.review?.next_complexity,true)}${field('volume-'+t.id,'Рекомендация по объёму следующего этапа',t.review?.next_volume,true)}<p class="small-note">Это правило войдёт в следующий запрос. Пустое поле отменяет специальную поправку. Тип «Редактирование документов» также применяется в API-редакторе.</p><button class="primary-button">Сохранить проверку и поправку</button></form>`:''}<details><summary>Точный запрос и сохранённая настройка</summary><pre class="raw-source">${escapeHTML(JSON.stringify(t.messages,null,2))}</pre></details></details>`).join('')||'<p>Задач пока нет. Первая задача станет начальной пробой.</p>';
  for(const [id,value] of drafts)if($(id))$(id).value=value;
  renderTaskPlans();
  if(adaptiveData.tasks.some(t=>t.status==='running'))adaptivePoll=setTimeout(async()=>{try{if(state.page!=='regulator')return;adaptiveData=await workspaceAPI('/api/adaptive');renderAdaptiveResults(true);}catch(error){workspaceError(error);}},2000);
}
document.addEventListener('input',e=>{if(e.target.id.startsWith('task-')||e.target.name==='rule-pack'){adaptivePreview=null;if($('adaptive-preview'))$('adaptive-preview').innerHTML='';}});
document.addEventListener('submit',async e=>{
  if(!['adaptive-profile','adaptive-task'].includes(e.target.id)&&!e.target.dataset.adaptiveReview)return;
  e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;
  try{
    if(e.target.id==='adaptive-profile'){
      await workspaceAPI('/api/adaptive/profile',{expected_revision:adaptiveData.profile.revision,purpose:$('profile-purpose').value,requirements:$('profile-requirements').value,starting_point:$('profile-starting').value,character_budget:Number($('profile-budget').value),known_terms:$('profile-known').value.split(';').map(x=>x.trim()).filter(Boolean)});await renderAdaptive();
    }else if(e.target.id==='adaptive-task'){
      adaptivePreview=await workspaceAPI('/api/adaptive/prepare',adaptivePayload());const r=adaptivePreview;
      $('adaptive-preview').innerHTML=`<h3>${r.gate==='ready'?'Запрос подготовлен':'Запрос превышает бюджет'}</h3><p>${escapeHTML(r.notice)}</p><p>${r.characters} / ${r.profile.character_budget} символов. ${escapeHTML(r.token_note)}</p>${runtimeManifestHTML(r.runtime)}${contextManifestHTML(r.retrieved_context)}<p>Способ следующей работы: ${escapeHTML(r.method||'Первоначальная проба.')}</p><p>Основания: ${r.experience_ids.length} проверенных человеком задач.</p><details><summary>Посмотреть точный запрос</summary><pre class="raw-source">${escapeHTML(JSON.stringify(r.messages,null,2))}</pre></details><div class="button-row">${r.gate==='ready'?'<button id="adaptive-start" class="primary-button">Выполнить через подключённый ИИ</button>':'<p>Уточните организацию задачи или бюджет. Материал сохраняется полностью.</p>'}<button id="adaptive-export" class="secondary-button">Скачать запрос для другого клиента</button></div>`;
    }else{
      const id=e.target.dataset.adaptiveReview,t=adaptiveData.tasks.find(t=>t.id===id);
      await workspaceAPI('/api/adaptive/review',{id,expected_revision:t.revision,outcome:e.target.elements.outcome.value,evidence:$('evidence-'+id).value,error:$('error-'+id).value,next_method:$('method-'+id).value,next_complexity:$('complexity-'+id).value,next_volume:$('volume-'+id).value});adaptiveData=await workspaceAPI('/api/adaptive');renderAdaptiveResults();$('workspace-message').textContent='Проверка сохранена. Следующая задача этого типа и модели получит актуальную поправку.';
    }
  }catch(error){workspaceError(error);}finally{button.disabled=false;}
});
document.addEventListener('click',async e=>{
  const b=e.target.closest('button');if(!b||!['adaptive-start','adaptive-export','adaptive-intake'].includes(b.id))return;
  b.disabled=true;
  try{
    if(b.id==='adaptive-export'&&adaptivePreview)downloadJSON('protocol-request.json',adaptivePreview);
    if(b.id==='adaptive-start'){if(!adaptivePreview)throw Error('Подготовьте запрос заново.');await workspaceAPI('/api/adaptive/start',{...adaptivePayload(),expected_request_sha256:adaptivePreview.request_sha256});adaptiveData=await workspaceAPI('/api/adaptive');renderAdaptiveResults();$('workspace-message').textContent='Запрос отправлен. После ответа потребуется проверка человеком.';}
    if(b.id==='adaptive-intake'){
      $('workspace-message').textContent='ИИ готовит постановку…';const r=await workspaceAPI('/api/adaptive/intake',adaptivePayload());
      for(const [key,value] of Object.entries(r.proposal))if($('task-'+key))$('task-'+key).value=value; if($('task-understanding'))$('task-understanding').open=true;
      adaptivePreview=null;$('adaptive-preview').innerHTML='';$('workspace-message').textContent='Постановка предложена ИИ. Проверьте тип, объём, сложность и критерии перед подготовкой запроса. Расход сервиса: '+JSON.stringify(r.usage);
    }
  }catch(error){workspaceError(error);}finally{b.disabled=false;}
});

function runtimeManifestHTML(runtime){
  if(!runtime)return '';
  return `<details class="runtime-manifest"><summary>Какие правила включены в запрос</summary><p>Краткие инструкции: ${runtime.characters} символов. Полный протокол: ${runtime.full_characters} символов.</p><p>Сокращается объясняющий текст правил; материалы задачи сохраняются полностью.</p>${runtime.rules.map(rule=>`<p><strong>§${escapeHTML(rule.section)}</strong> ${escapeHTML(rule.title)} — ${escapeHTML(rule.reason)}</p>`).join('')}<details><summary>Посмотреть передаваемые инструкции</summary><pre class="raw-source">${escapeHTML(runtime.text)}</pre></details>${runtime.omitted.length?`<details><summary>Какие группы не включены</summary>${runtime.omitted.map(item=>`<p>§${escapeHTML(item.section)} — ${escapeHTML(item.reason)}</p>`).join('')}</details>`:''}</details>`;
}

function contextManifestHTML(context){
  if(!context)return '';
  const groups=context.memory?.groups||{};
  return `<details class="runtime-manifest"><summary>Какие основания восстановлены</summary><p>${escapeHTML(context.method)}. ${context.characters} / ${context.budget} символов.</p><p>${escapeHTML(context.limits)}</p>${context.included.map(item=>`<p><strong>${escapeHTML(item.title)}</strong><br>${escapeHTML(item.reason)}</p>`).join('')}${context.memory_matches.map(item=>`<p>Память: ${escapeHTML(item.title)}<br>${escapeHTML(item.reason)}</p>`).join('')}${context.mandatory_ids.length?`<p>Обязательные ограничения: ${context.mandatory_ids.map(escapeHTML).join(', ')}</p>`:''}<p>Принятые записи: ${(groups.accepted||[]).length}; материалы источников: ${(groups.source_material||[]).length}; предложения и гипотезы: ${(groups.proposals_and_hypotheses||[]).length}; история: ${(groups.historical_or_rejected||[]).length}.</p>${context.omitted.length?`<h3>Найдено, но не передано</h3>${context.omitted.map(item=>`<p>${escapeHTML(item.title)}: ${escapeHTML(item.reason)}</p>`).join('')}`:''}<details><summary>Источники, версии и точные фрагменты</summary>${Object.entries(context.references).map(([id,r])=>r.type==='source'?`<article><h3>${escapeHTML(id)} · ${escapeHTML(r.path)}</h3><p>Строки ${r.start_line}–${r.end_line}, версия ${escapeHTML(r.sha256.slice(0,12))}</p><blockquote>${escapeHTML(r.quote)}</blockquote></article>`:`<p>${escapeHTML(id)} · ${escapeHTML(r.title)} · версия ${r.revision} · ${escapeHTML(memoryStatuses[r.status]||r.status)}</p>`).join('')}</details></details>`;
}
function taskEvidenceHTML(task){
  const resolved=task.resolved_answer,analysis=task.checks?.analysis;
  const calculations=[...(resolved?.calculations||[]),...(analysis?.calculations||[])];
  return `${task.requires_recheck?.length?`<div class="notice"><p>Основания результата изменились. Требуется повторная проверка.</p>${task.requires_recheck.map(reason=>`<p>${escapeHTML(reason)}</p>`).join('')}</div>`:''}<details open class="runtime-manifest"><summary>Свидетельства и проверки приложения</summary><p>Сведения ниже сформированы приложением. Оценка смысла и принятие результата остаются человеку.</p>${(task.events||[]).map(e=>`<p>${escapeHTML(e.summary)}<br><small>${escapeHTML(e.scope)}</small></p>`).join('')}${task.checks?.validation_error?`<p class="notice">${escapeHTML(task.checks.validation_error)}</p>`:''}${calculations.length?`<h3>Вычисления</h3>${calculations.map(c=>`<p>${escapeHTML(c.left)} = ${escapeHTML(c.right)}: <strong>${escapeHTML({pass:'равенство подтверждено',fail:'равенство не выполняется',unknown:'проверка вне поддерживаемой области'}[c.status])}</strong>${c.computed?' · получено '+escapeHTML(c.computed):''}<br><small>${escapeHTML(c.scope)}</small></p>`).join('')}`:''}${(analysis?.terms||[]).map(w=>`<p>Понятие «${escapeHTML(w.term)}»: ${escapeHTML(w.message)}</p>`).join('')}${resolved?`<h3>Рассмотрение критериев</h3>${resolved.coverage.map(c=>`<p>${escapeHTML(task.criteria_items.find(k=>k.id===c.criterion_id)?.text||c.criterion_id)}: ${escapeHTML({addressed:'ИИ указал связанные утверждения; достаточность ещё предстоит оценить',not_addressed:'не рассмотрено',unknown:'остаётся неизвестным'}[c.state])}${c.note?' · '+escapeHTML(c.note):''}</p>`).join('')}<details><summary>Объяснённые переходы и их основания</summary><p>${escapeHTML(resolved.transitions.limits)}</p>${resolved.transitions.steps.map(s=>`<article><h3>${escapeHTML(s.change)}</h3><p>${escapeHTML(s.output)}</p><p>Причина: ${escapeHTML(s.reason||'не установлена')}</p><p>Условия: ${escapeHTML(s.conditions||'не указаны')}</p><p>Входные основания: ${s.inputs.map(escapeHTML).join(', ')}</p></article>`).join('')||'<p>Отдельные переходы в этом ответе не представлены.</p>'}</details><details><summary>Утверждения и зафиксированные основания</summary><pre class="raw-source">${escapeHTML(JSON.stringify(resolved.claims,null,2))}</pre></details>`:''}</details>`;
}
function taskCritiquesHTML(task){
  if(!task.answer)return '';
  return `<details class="runtime-manifest"><summary>Дополнительный анализ оснований</summary><p>По вашему действию ИИ рассмотрит объяснение и источники в отдельном запросе. Используется текущее подключение редактора; расход сохраняется отдельно. Замечания служат материалом для проверки человеком.</p><button type="button" class="secondary-button" data-task-critique="${task.id}">Рассмотреть основания с ИИ</button>${(task.critiques||[]).map(c=>`<article><p>${escapeHTML({completed:'Анализ получен',invalid_response:'Ответ анализа не прошёл проверку ссылок и цитат',result_changed:'Во время анализа результат изменился'}[c.status]||c.status)}</p><p>${escapeHTML(c.limits)}</p>${c.issues.map(i=>`<blockquote>${escapeHTML(i.quote)}</blockquote><p>${escapeHTML(i.problem)}</p><p>${escapeHTML(i.question)}</p>`).join('')}${c.status==='completed'&&!c.issues.length?'<p>Модель не указала затруднений. Это не подтверждение правильности.</p>':''}<p>Расход сервиса: ${escapeHTML(JSON.stringify(c.usage))}</p></article>`).join('')}</details>`;
}

let planDraft=null;
const stageLabels={ready:'можно выполнять',blocked:'ожидает входной результат',running:'выполняется',awaiting_review:'ожидает решения человека',accepted:'принят человеком',needs_recheck:'нужна повторная проверка'};
function renderTaskPlans(){
  if(!$('task-plans'))return;
  if($('task-stage')){
    const selected=$('task-stage').value;
    const entries=(adaptiveData.plans||[]).flatMap(p=>p.stages.filter(stage=>['ready','needs_recheck'].includes(stage.status)&&!stage.blockers.length).map(stage=>`<option value="${p.id}:${stage.id}">${escapeHTML(p.goal)} → ${escapeHTML(stage.title)}</option>`)).join('');
    $('task-stage').innerHTML='<option value="">Самостоятельная задача</option>'+entries;
    $('task-stage').value=[...$('task-stage').options].some(o=>o.value===selected)?selected:'';
  }

  $('task-plans').innerHTML=(adaptiveData.plans||[]).map(p=>`<article><h3>${escapeHTML(p.goal)} · версия ${p.revision}</h3>${p.stages.map(stage=>`<p><strong>${escapeHTML(stage.title)}</strong>: ${escapeHTML(stageLabels[stage.status])}<br>${stage.requires.length?'Входные этапы: '+stage.requires.map(id=>escapeHTML(p.stages.find(s=>s.id===id)?.title||id)).join(', '):'Начальный этап'}${stage.blockers.map(b=>'<br>'+escapeHTML(b)).join('')}</p>`).join('')}<button type="button" class="secondary-button" data-plan-edit="${p.id}">Пересмотреть схему</button></article>`).join('')||'<p>Схем пока нет. Для самостоятельной задачи они не требуются.</p>';
}
function readPlanDraft(){
  if(!planDraft||!$('plan-goal'))return;
  planDraft.goal=$('plan-goal').value;
  for(const stage of planDraft.stages){stage.title=$('plan-title-'+stage.id).value;stage.requires=[...document.querySelectorAll(`[name="plan-deps-${stage.id}"]:checked`)].map(e=>e.value);}
}
function renderPlanEditor(){
  $('plan-editor').innerHTML=`<form id="plan-form">${field('plan-goal','Общая цель связанных этапов',planDraft.goal)}${planDraft.stages.map((stage,index)=>`<fieldset class="rule-pack-options"><legend>Этап ${index+1}</legend>${field('plan-title-'+stage.id,'Какой результат должен получить этап',stage.title)}<p>Какие результаты нужны до начала этого этапа:</p>${planDraft.stages.filter(s=>s.id!==stage.id).map(s=>`<label class="checkbox-label"><input name="plan-deps-${stage.id}" type="checkbox" value="${s.id}" ${stage.requires.includes(s.id)?'checked':''}>${escapeHTML(s.title||'Этап '+(planDraft.stages.indexOf(s)+1))}</label>`).join('')||'<p>Других этапов пока нет.</p>'}</fieldset>`).join('')}<div class="button-row"><button type="button" id="plan-add" class="secondary-button">Добавить этап</button><button class="primary-button">Принять схему для этой цели</button></div></form>`;
}
document.addEventListener('click',async e=>{
  const b=e.target.closest('button');if(!b)return;
  if(b.id==='plan-new'||b.dataset.planEdit){const existing=adaptiveData.plans?.find(p=>p.id===b.dataset.planEdit);planDraft=existing?{id:existing.id,revision:existing.revision,goal:existing.goal,stages:existing.stages.map(({id,title,requires})=>({id,title,requires:[...requires]}))}:{goal:'',stages:[{id:'stage1',title:'',requires:[]}]};renderPlanEditor();return;}
  if(b.id==='plan-add'){readPlanDraft();if(planDraft.stages.length>=30){workspaceError(Error('Не более 30 этапов.'));return;}let i=1;while(planDraft.stages.some(s=>s.id==='stage'+i))i++;planDraft.stages.push({id:'stage'+i,title:'',requires:[]});renderPlanEditor();return;}
  if(b.id==='task-diagnostics'){
    try{const r=await workspaceAPI('/api/adaptive/diagnostics');$('task-diagnostics-result').innerHTML=`<p>${escapeHTML(r.limits)}</p>${r.groups.map(g=>`<article><h3>${escapeHTML(g.task_type)} · ${escapeHTML(g.model.model)}</h3><p>Проверено человеком: ${g.reviewed}; принято: ${g.accepted}; основания изменились: ${g.requires_recheck}.</p>${Object.values(g.errors).map(error=>`<p>${escapeHTML(error.text)} · случаев: ${error.task_ids.length}</p>${error.corrections.map(c=>'<p>Принятая поправка: '+escapeHTML(c.method)+'</p>').join('')}`).join('')}</article>`).join('')}<p>${escapeHTML(r.retention.reason)}</p><p>Защищено результатов: ${r.retention.protected_task_ids.length}. Кандидатов для обсуждения удаления: ${r.retention.candidate_task_ids.length}. Действие удаления не выполняется.</p>`;}catch(error){workspaceError(error);}return;
  }
  if(b.dataset.taskCritique){b.disabled=true;try{const task=adaptiveData.tasks.find(t=>t.id===b.dataset.taskCritique);$('workspace-message').textContent='ИИ рассматривает основания отдельным запросом…';await workspaceAPI('/api/adaptive/critique',{id:task.id,expected_revision:task.revision});adaptiveData=await workspaceAPI('/api/adaptive');renderAdaptiveResults(true);$('workspace-message').textContent='Замечания и расход анализа сохранены. Решение о результате остаётся вам.';}catch(error){workspaceError(error);}finally{b.disabled=false;}}
});
document.addEventListener('submit',async e=>{
  if(e.target.id!=='plan-form')return;e.preventDefault();readPlanDraft();
  try{await workspaceAPI('/api/adaptive/plan',{id:planDraft.id,expected_revision:planDraft.revision||0,goal:planDraft.goal,stages:planDraft.stages,approved:true});await renderAdaptive();$('workspace-message').textContent='Схема принята. Доступные этапы появились в постановке задачи.';}catch(error){workspaceError(error);}
});

function renderProgramChecks(){
  if(!$('task-program-checks'))return;
  $('task-program-checks').innerHTML=(adaptiveData.program_checks||[]).map(c=>`<p>Тесты проекта: ${c.status==='pass'?'успешно завершены':'проверка неуспешна'}, случаев: ${c.count??'неизвестно'}. ${c.current?'Соответствует текущим файлам.':'Файлы изменились после проверки.'}</p><p class="small-note">${escapeHTML(c.scope)}</p>`).join('')||'<p class="small-note">Проверка текущей программы ещё не запускалась через приложение. События внешнего терминала автоматически не приписываются этому запуску.</p>';
}
document.addEventListener('click',async e=>{
  const b=e.target.closest('button');if(b?.id!=='task-check-program')return;
  b.disabled=true;
  try{$('workspace-message').textContent='Выполняются тесты проекта…';await workspaceAPI('/api/adaptive/check-program',{});adaptiveData=await workspaceAPI('/api/adaptive');renderProgramChecks();adaptivePreview=null;$('adaptive-preview').innerHTML='';$('workspace-message').textContent='Результат тестов и версия файлов сохранены.';}catch(error){workspaceError(error);}finally{b.disabled=false;}
});
